@SuppressWarnings("serial")
@Test
public void testThrowableMessage() {
    // #43398
    BuildException be = new BuildException("oops", new Location("build.xml", 1, 0));
    assertEquals(String.format("build.xml:1: oops%n"), msg(be, false));
    be = ProjectHelper.addLocationToBuildException(be, new Location("build.xml", 2, 0));
    assertEquals(String.format("build.xml:2: The following error occurred while executing this line:%n" + "build.xml:1: oops%n"), msg(be, false));
    be = ProjectHelper.addLocationToBuildException(be, new Location("build.xml", 3, 0));
    assertEquals(String.format("build.xml:3: The following error occurred while executing this line:%n" + "build.xml:2: The following error occurred while executing this line:%n" + "build.xml:1: oops%n"), msg(be, false));
    Exception x = new Exception("problem") {

        public void printStackTrace(PrintWriter w) {
            w.println("problem");
            w.println("  at p.C.m");
        }
    };
    assertEquals(String.format("problem%n  at p.C.m%n"), msg(x, false));
    be = new BuildException(x, new Location("build.xml", 1, 0));
    assertEquals(String.format("build.xml:1: problem%n  at p.C.m%n"), msg(be, false));
    be = ProjectHelper.addLocationToBuildException(be, new Location("build.xml", 2, 0));
    assertEquals(String.format("build.xml:2: The following error occurred while executing this line:%n" + "build.xml:1: problem%n  at p.C.m%n"), msg(be, false));
}

