// test that the watchdog ends the process
@Test
public void testTimeOut() {
    Commandline cmd = getCommandline(TIME_OUT * 2);
    ej.setJavaCommand(cmd);
    long now = System.currentTimeMillis();
    ej.execute(project);
    long elapsed = System.currentTimeMillis() - now;
