@Test
public void testExcludeResources() throws IOException {
    buildRule.executeTarget("excluderesources");
    ImageStructure image = verifyImageBuiltNormally();
    String mainClass = buildRule.getProject().getProperty("hello.main-class");
    Assert.assertNotNull("Checking that main-class property exists", mainClass);
    ProcessBuilder builder = new ProcessBuilder(image.java.toString(), mainClass, "resource1.txt", "resource2.txt");
    builder.redirectInput(ProcessBuilder.Redirect.INHERIT);
    builder.redirectErrorStream(true);
    Collection<String> outputLines;
    Process process = builder.start();
    try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
        outputLines = reader.lines().collect(Collectors.toList());
    }
    Assert.assertTrue("Checking that excluded resource is actually excluded.", outputLines.stream().anyMatch(l -> l.endsWith("resource1.txt absent")));
    Assert.assertTrue("Checking that resource not excluded is present.", outputLines.stream().anyMatch(l -> l.endsWith("resource2.txt present")));
}

