@Test
public void testDeduplicationOfLicenses() {
    buildRule.executeTarget("dedup");
    ImageStructure image = verifyImageBuiltNormally();
    String helloModuleName = buildRule.getProject().getProperty("hello.mod");
    String smileModuleName = buildRule.getProject().getProperty("smile.mod");
    Assert.assertNotNull("Checking that 'hello.mod' property was set.", helloModuleName);
    Assert.assertNotNull("Checking that 'smile.mod' property was set.", smileModuleName);
    Assume.assumeFalse("Checking that this operating system" + " supports symbolic links as a means of license de-duplication.", System.getProperty("os.name").contains("Windows"));
    Path legal = image.root.toPath().resolve("legal");
    Path[] licenses = { legal.resolve(helloModuleName).resolve("USELESSLICENSE"), legal.resolve(smileModuleName).resolve("USELESSLICENSE") };
    int nonLinkCount = 0;
    for (Path license : licenses) {
        if (!Files.isSymbolicLink(license)) {
            nonLinkCount++;
        }
    }
    Assert.assertEquals("Checking that USELESSLICENSE only exists once in image " + "and all other instances are links to it.", 1, nonLinkCount);
}

