@Test
public void testBindingOfServices() throws IOException, InterruptedException {
    buildRule.executeTarget("bindservices");
    ImageStructure image = verifyImageBuiltNormally();
    String mainClass = buildRule.getProject().getProperty("inc.main-class");
    ProcessBuilder builder = new ProcessBuilder(image.java.toString(), mainClass);
    builder.redirectInput(ProcessBuilder.Redirect.INHERIT);
    builder.redirectError(ProcessBuilder.Redirect.INHERIT);
    Process process = builder.start();
    try (BufferedReader linesReader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
        Assert.assertEquals("Checking that bindServices=false results in no providers in image.", 0, linesReader.lines().count());
    }
    process.waitFor();
    image = new ImageStructure(new File(buildRule.getProject().getProperty("image2")));
    Assert.assertTrue("Checking that image2 was successfully created.", image.root.exists());
    Assert.assertTrue("Checking that image2 has java executable.", image.java.exists());
    builder = new ProcessBuilder(image.java.toString(), mainClass);
    builder.redirectInput(ProcessBuilder.Redirect.INHERIT);
    builder.redirectError(ProcessBuilder.Redirect.INHERIT);
    process = builder.start();
    try (BufferedReader linesReader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
        Assert.assertEquals("Checking that bindServices=true results in image with provider.", 5, linesReader.lines().count());
    }
    process.waitFor();
}

