@Test
public void testJunitOnCpArguments() throws Exception {
    //NOI18N
    final File tmp = new File(System.getProperty("java.io.tmpdir"));
    final File workDir = new File(tmp, //NOI18N
    String.//NOI18N
    format(//NOI18N
    "%s_testJCP%d", getClass().getName(), System.currentTimeMillis() / 1000));
    workDir.mkdirs();
    try {
        //NOI18N
        final File modulesDir = new File(workDir, "modules");
        modulesDir.mkdirs();
        final Project project = new Project();
        project.init();
        project.setBaseDir(workDir);
        final MockCommandLauncher mockProcLauncher = new MockCommandLauncher();
        project.addReference(MagicNames.ANT_VM_LAUNCHER_REF_ID, mockProcLauncher);
        JUnitTask task = new JUnitTask();
        task.setDir(workDir);
        task.setFork(true);
        task.setProject(project);
        final File junit = LoaderUtils.getResourceSource(JUnitTask.class.getClassLoader(), //NOI18N
        "junit/framework/Test.class");
        final Path cp = new Path(project);
        cp.setPath(junit.getAbsolutePath());
        task.createClasspath().add(cp);
        final Path mp = new Path(project);
        mp.setPath(modulesDir.getName());
        task.createModulepath().add(mp);
        task.addTest(new JUnitTest("org.apache.tools.ant.taskdefs.optional.junit.TestTest"));
        task.execute();
        assertNotNull(mockProcLauncher.cmd);
        String resCp = null;
        String resMp = null;
        Set<String> resExports = new TreeSet<>();
        for (int i = 1; i < mockProcLauncher.cmd.length; i++) {
            if ("-classpath".equals(mockProcLauncher.cmd[i])) {
                //NOI18N
                resCp = mockProcLauncher.cmd[++i];
            } else if ("--module-path".equals(mockProcLauncher.cmd[i])) {
                //NOI18N
                resMp = mockProcLauncher.cmd[++i];
            } else if (mockProcLauncher.cmd[i].equals("--add-exports")) {
                //NOI18N
                resExports.add(mockProcLauncher.cmd[++i]);
            } else if (JUnitTestRunner.class.getName().equals(mockProcLauncher.cmd[i])) {
                break;
            }
        }
        assertTrue("No exports", resExports.isEmpty());
        if (project.getProperty(MagicNames.BUILD_SYSCLASSPATH) == null && System.getProperty(MagicNames.BUILD_SYSCLASSPATH) == null && project.getProperty("tests.and.ant.share.classloader") == null) {
            assertEquals("Expected classpath", cp.toString(), resCp);
        }
        assertEquals("Expected modulepath", mp.toString(), resMp);
    } finally {
        delete(workDir);
    }
}

