@Test
public void testResolveFileDosOrNetware() {
    assumeTrue("Not DOS or Netware", Os.isFamily("dos") || Os.isFamily("netware"));
    assertEqualsIgnoreDriveCase(localize(File.separator), getFileUtils().resolveFile(null, "/").getPath());
    assertEqualsIgnoreDriveCase(localize(File.separator), getFileUtils().resolveFile(null, "\\").getPath());
    /*
         * throw in drive letters
         */
    String driveSpec = "C:";
    assertEquals(driveSpec + "\\", getFileUtils().resolveFile(null, driveSpec + "/").getPath());
    assertEquals(driveSpec + "\\", getFileUtils().resolveFile(null, driveSpec + "\\").getPath());
    String driveSpecLower = "c:";
    assertEquals(driveSpecLower + "\\", getFileUtils().resolveFile(null, driveSpecLower + "/").getPath());
    assertEquals(driveSpecLower + "\\", getFileUtils().resolveFile(null, driveSpecLower + "\\").getPath());
    /*
         * promised to eliminate consecutive slashes after drive letter.
         */
    assertEquals(driveSpec + "\\", getFileUtils().resolveFile(null, driveSpec + "/////").getPath());
    assertEquals(driveSpec + "\\", getFileUtils().resolveFile(null, driveSpec + "\\\\\\\\\\\\").getPath());
    if (Os.isFamily("netware")) {
        /*
             * throw in NetWare volume names
             */
        driveSpec = "SYS:";
        assertEquals(driveSpec, getFileUtils().resolveFile(null, driveSpec + "/").getPath());
        assertEquals(driveSpec, getFileUtils().resolveFile(null, driveSpec + "\\").getPath());
        driveSpecLower = "sys:";
        assertEquals(driveSpec, getFileUtils().resolveFile(null, driveSpecLower + "/").getPath());
        assertEquals(driveSpec, getFileUtils().resolveFile(null, driveSpecLower + "\\").getPath());
        /*
             * promised to eliminate consecutive slashes after drive letter.
             */
        assertEquals(driveSpec, getFileUtils().resolveFile(null, driveSpec + "/////").getPath());
        assertEquals(driveSpec, getFileUtils().resolveFile(null, driveSpec + "\\\\\\\\\\\\").getPath());
    }
}

