             * throw in NetWare volume names
             */
        String driveSpec = "SYS:";
        assertEquals(driveSpec, getFileUtils().normalize(driveSpec).getPath());
        assertEquals(driveSpec, getFileUtils().normalize(driveSpec + "/").getPath());
        assertEquals(driveSpec, getFileUtils().normalize(driveSpec + "\\").getPath());
        String driveSpecLower = "sys:";
        assertEquals(driveSpec, getFileUtils().normalize(driveSpecLower).getPath());
        assertEquals(driveSpec, getFileUtils().normalize(driveSpecLower + "/").getPath());
        assertEquals(driveSpec, getFileUtils().normalize(driveSpecLower + "\\").getPath());
        assertEquals(driveSpec + "\\junk", getFileUtils().normalize(driveSpecLower + "\\junk").getPath());
        /*
             * promised to eliminate consecutive slashes after drive letter.
             */
        assertEquals(driveSpec, getFileUtils().normalize(driveSpec + "/////").getPath());
        assertEquals(driveSpec, getFileUtils().normalize(driveSpec + "\\\\\\\\\\\\").getPath());
    }
}

