@Test
public void testIso88591ToUtf8() throws Exception {
    ByteArrayOutputStream actualOS = new ByteArrayOutputStream();
    try (ReaderInputStream r = new ReaderInputStream(new InputStreamReader(new FileInputStream(new File(ROOT, "src/tests/antunit/taskdefs/exec/input/iso8859-1")), StandardCharsets.ISO_8859_1), StandardCharsets.UTF_8)) {
        int b = r.read();
        while (b > -1) {
            actualOS.write((byte) b);
            b = r.read();
        }
    }
    ByteArrayOutputStream expectedOS = new ByteArrayOutputStream();
    try (FileInputStream utf8 = new FileInputStream(new File(ROOT, "src/tests/antunit/taskdefs/exec/expected/utf-8"))) {
        int b = utf8.read();
        while (b > -1) {
            expectedOS.write((byte) b);
            b = utf8.read();
        }
    }
    byte[] expected = expectedOS.toByteArray();
    byte[] actual = actualOS.toByteArray();
    assertEquals("length", expected.length, actual.length);
    for (int i = 0; i < actual.length; i++) {
        assertEquals("byte " + i, expected[i], actual[i]);
    }
}

