    byte[] local = ExtraFieldUtils.mergeLocalFileDataData(new ZipExtraField[] { a, d });
    assertEquals("local length", data.length - 1, local.length);
    for (int i = 0; i < local.length; i++) {
        assertEquals("local byte " + i, data[i], local[i]);
